---InitData
---@param quizzed table
---@param pvpArenaDojo PVPArenaDojo
---@param count number
function PVPArenaQuizListDialog:InitData(quizzed, pvpArenaDojo, count)
    local listData    = {}
    if count <= 0 then
        return listData
    end
    local matcherInfo = checkTable(pvpArenaDojo.matcherInfo)
    local CreateData = function(playerId, positionData, cellState, rank, rewardNum)
        return {
            cellState = cellState,
            positionData = positionData,
            playerId = playerId,
            info = matcherInfo[tostring(playerId)],
            rank = rank,
            rewardNum = rewardNum,
        }
    end

    local map                     = checkTable(pvpArenaDojo.map)
    local pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()
    local isInBattle   = checkNumber(pvpArenaEntryDojo.battleStatus) == Constants.PVPArenaBattleStatus.InBattle
    --local battleRound             = checkNumber(pvpArenaDojo.battleRound)
    --if checkNumber(pvpArenaDojo.battleStatus) == Constants.PVPArenaBattleStatus.Wait then
    --    battleRound = battleRound + 1
    --end
    local curWheel                = pvpArenaComponent:GetCurWheel()
    local quizFailRewardsNum      = pvpArenaComponent:GetQuizFailRewardsNum()
    local quizSuccessRewardsNum   = pvpArenaComponent:GetQuizSuccessRewardsNum()
    local playerId2ExpectPosition = pvpArenaComponent:GetPlayerId2ExpectPosition()
    local matchChartTotalWheelNum = pvpArenaComponent:GetMatchChartTotalWheelNum()
    local wheelCount = matchChartTotalWheelNum - 1
    --local isLastDisplayWheel      = curWheel == matchChartTotalWheelNum

    for i, playerId in ipairs(quizzed) do
        local expectPositions = playerId2ExpectPosition[tostring(playerId)]
        local expectPositionCount = #expectPositions
        playerId = checkNumber(playerId)
        local endWheel = curWheel
        local rewardNum = 0
        local isSameScore = false
        local isWin = false
        local rank, positionData
        for wheel = endWheel, 1, -1 do
            local expectPosition     = expectPositions[wheel]
            local expectPositionData = map[tostring(expectPosition)] or {}
            if checkNumber(expectPositionData.playerId) == playerId then
                positionData = expectPositionData
                --- 找到对手的站位数据
                local rivalPosition     = expectPosition % 2 == 1 and expectPosition + 1 or expectPosition - 1
                local rivalPositionData = map[tostring(rivalPosition)]
                --- 如果没有对手 那么就是获胜了 不用继续循环了 这时计算一下奖励个数
                if not rivalPositionData then
                    rewardNum = pvpArenaComponent:CalcTotalQuizRewardsNumByWheel(wheel)
                    isWin = true
                    break
                end
                --- 有对手 判断胜负关系
                local playerScore = checkNumber(expectPositionData.score)
                local rivalScore  = checkNumber(rivalPositionData.score)
                isWin = playerScore > rivalScore
                if isWin then
                    rewardNum = pvpArenaComponent:CalcTotalQuizRewardsNumByWheel(wheel, true)
                    break
                end
                isSameScore = playerScore == rivalScore
                if isSameScore then
                    break
                end

                rank = 2 ^ (wheelCount - wheel + 1)
                --- 比赛失败
                rewardNum = pvpArenaComponent:CalcTotalQuizRewardsNumByWheel(wheel, false)
                break
            end
        end

        if curWheel >= wheelCount then
            --- 检查季军赛
            local leftPosition      = expectPositions[expectPositionCount - 1]
            local rightPosition     = expectPositions[expectPositionCount]
            local leftPositionData  = map[tostring(leftPosition)] or {}
            local rightPositionData = map[tostring(rightPosition)] or {}

            local CheckState = function(winPositionData, loserPositionData)
                if checkNumber(winPositionData.playerId) ~= playerId then return end

                positionData = winPositionData
                local playerScore = checkNumber(winPositionData.score)
                local rivalScore  = checkNumber(loserPositionData.score)
                isWin = playerScore > rivalScore
                isSameScore = playerScore == rivalScore
                if not isSameScore then
                    rewardNum = rewardNum + (isWin and quizSuccessRewardsNum or quizFailRewardsNum)
                    rank = isWin and 3 or 4
                end
            end

            CheckState(leftPositionData, rightPositionData)
            CheckState(rightPositionData, leftPositionData)

        end

        if isSameScore then
            local cellState = isInBattle and CellState.InBattle or CellState.Prepare
            table.insert(listData, CreateData(playerId, positionData, cellState))
        else
            local cellState = CellState.RewardPreview
            table.insert(listData, CreateData(playerId, positionData, cellState, rank, rewardNum))
        end

    end

    return listData
end

