function PVPArenaQuizListDialog:RefreshUI()
    local pvpArenaDojo = pvpArenaComponent:GetPVPArenaDojo()
    local quizzed      = checkTable(pvpArenaDojo.quizzed)
    local count        = #quizzed
    local isEmpty      = count <= 0
    self.listData      = self:InitData(quizzed, pvpArenaDojo, count)
    KTool.SetActive(self.EmptyNode.gameObject, isEmpty)

    local LoopViewPlayer = self.LoopViewPlayer
    KTool.SetActive(LoopViewPlayer.gameObject, not isEmpty)
    if not isEmpty then
        if not LoopViewPlayer.IsListViewInit then
            LoopViewPlayer:InitListView(count, Bind(self, self.OnGetItemByIndex))
        else
            GameUtils.ReloadData(LoopViewPlayer, count)
        end
    end
end
function PVPArenaQuizListDialog:OnGetItemByIndex(listView, idx)
    if idx < 0 then return end
    local index = idx + 1
    local data = self.listData[index]

    local cell = listView:NewListViewItem(NodeName)
    local node = GetLuaBehaviour(cell.gameObject, NodePath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
    end
    if not KTool.IsNull(node) then
        local mbEnv = node.Env
        mbEnv:RefreshUI(data, self.quizRewardGoodsId)
    end

    return cell
end
